    async function renderSites() {
      setMessage('\u6B63\u5728\u8BFB\u53D6\u7AD9\u6E90\u5217\u8868...');
      $('detailBody').innerHTML = '<div class="status">\u7AD9\u6E90\u52A0\u8F7D\u4E2D...</div>';
      try {
        const result = await api('/website/api/sites');
        editingSites = Array.isArray(result.data) ? result.data : [];
        renderSiteEditor(0, { keepVisible: false });
      } catch (error) {
        handleError(error);
      }
    }

    function renderSiteEditor(selected, options) {
      const opts = options || {};
      const enabled = editingSites.filter(site => site.enable !== false).length;
      setMessage('\u5F53\u524D\u542F\u7528 ' + enabled + ' / ' + editingSites.length + ' \u4E2A\u7AD9\u6E90\uFF0C\u4FDD\u5B58\u540E /config \u4F1A\u6309\u8FD9\u91CC\u7684\u987A\u5E8F\u8F93\u51FA\u3002');
      $('detailBody').innerHTML =
        actions([['enableAllSites','\u5168\u90E8\u542F\u7528','secondary'],['disableAllSites','\u5168\u90E8\u505C\u7528','ghost'],['resetSites','\u91CD\u7F6E','danger'],['saveSites','\u4FDD\u5B58','primary']]) +
        '<div class="site-list">' + editingSites.map((site, index) => siteRowHtml(site, index, selected)).join('') + '</div>';
      document.querySelectorAll('[data-site-toggle]').forEach((node) => {
        node.onchange = () => {
          const index = Number(node.dataset.index);
          if (!editingSites[index]) return;
          editingSites[index].enable = node.checked;
          renderSiteEditor(index);
        };
      });
      document.querySelectorAll('[data-site-up]').forEach((node) => node.onclick = () => moveSite(Number(node.dataset.index), -1));
      document.querySelectorAll('[data-site-down]').forEach((node) => node.onclick = () => moveSite(Number(node.dataset.index), 1));
      bindSiteDragEvents();
      $('enableAllSites').onclick = () => setAllSites(true);
      $('disableAllSites').onclick = () => setAllSites(false);
      $('resetSites').onclick = resetSites;
      $('saveSites').onclick = saveSites;
      if (opts.keepVisible !== false) focusSiteRow(selected);
    }

    function siteRowHtml(site, index, selected) {
      const cls = ['site-row'];
      if (site.enable === false) cls.push('disabled');
      if (index === selected) cls.push('selected');
      return '<div class="' + cls.join(' ') + '" data-index="' + index + '">' +
        '<div class="site-drag" title="\u6309\u4F4F\u62D6\u52A8\u6392\u5E8F" data-site-drag data-index="' + index + '" draggable="true"><span class="site-drag-mark">::</span><span>\u62D6\u52A8\u6392\u5E8F</span></div>' +
        '<label class="site-toggle"><input type="checkbox" data-site-toggle data-index="' + index + '" ' + (site.enable !== false ? 'checked' : '') + '><span>\u542F\u7528</span></label>' +
        '<div class="site-main"><div class="site-name">' + escapeHtml(site.name || site.key) + '</div><div class="site-meta">' + (index + 1) + '. ' + escapeHtml(site.key) + ' \xB7 ' + siteTypeName(site.type) + '</div></div>' +
        '<div class="site-move"><button data-site-up data-index="' + index + '" ' + (index <= 0 ? 'disabled' : '') + '>\u4E0A</button><button data-site-down data-index="' + index + '" ' + (index >= editingSites.length - 1 ? 'disabled' : '') + '>\u4E0B</button></div>' +
        '</div>';
    }

    function moveSite(index, step) {
      const next = index + step;
      if (next < 0 || next >= editingSites.length) return;
      const item = editingSites[index];
      editingSites[index] = editingSites[next];
      editingSites[next] = item;
      renderSiteEditor(next);
    }

    function bindSiteDragEvents() {
      document.querySelectorAll('.site-row').forEach((row) => {
        row.ondragstart = (event) => {
          draggingSiteIndex = Number(row.dataset.index);
          row.classList.add('dragging');
          if (event.dataTransfer) {
            event.dataTransfer.effectAllowed = 'move';
            event.dataTransfer.setData('text/plain', String(draggingSiteIndex));
          }
        };
        row.ondragend = () => {
          draggingSiteIndex = -1;
          document.querySelectorAll('.site-row').forEach(item => item.classList.remove('dragging','drag-over'));
        };
        row.ondragover = (event) => {
          event.preventDefault();
          const target = Number(row.dataset.index);
          if (target !== draggingSiteIndex) row.classList.add('drag-over');
          if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
        };
        row.ondragleave = () => row.classList.remove('drag-over');
        row.ondrop = (event) => {
          event.preventDefault();
          row.classList.remove('drag-over');
          const from = draggingSiteIndex >= 0 ? draggingSiteIndex : Number(event.dataTransfer && event.dataTransfer.getData('text/plain'));
          const to = Number(row.dataset.index);
          moveSiteTo(from, to);
        };
      });
    }

    function moveSiteTo(from, to) {
      if (from < 0 || from >= editingSites.length || to < 0 || to >= editingSites.length || from === to) return;
      const item = editingSites.splice(from, 1)[0];
      editingSites.splice(to, 0, item);
      draggingSiteIndex = -1;
      renderSiteEditor(to);
    }

    function focusSiteRow(index) {
      setTimeout(() => {
        const row = document.querySelector('.site-row[data-index="' + index + '"]');
        if (!row) return;
        row.scrollIntoView({ block: 'center', inline: 'nearest' });
      }, 0);
    }

    function setAllSites(enable) {
      editingSites = editingSites.map(site => Object.assign({}, site, { enable }));
      renderSiteEditor(0);
    }

    async function saveSites() {
      await api('/website/api/sites',{method:'PUT',body:JSON.stringify({list: editingSites})});
      toast('\u7AD9\u6E90\u8BBE\u7F6E\u5DF2\u4FDD\u5B58');
      await renderSites();
    }

    async function resetSites() {
      await api('/website/api/sites',{method:'DELETE'});
      toast('\u7AD9\u6E90\u8BBE\u7F6E\u5DF2\u91CD\u7F6E');
      await renderSites();
    }

    function siteTypeName(type) {
      const value = Number(type || 3);
      if (value < 10) return '\u89C6\u9891';
      if (value < 20) return '\u9605\u8BFB';
      if (value < 30) return '\u6F2B\u753B';
      if (value < 40) return '\u97F3\u4E50';
      if (value < 50) return '\u7F51\u76D8';
      return '\u5176\u4ED6';
    }

