    function openRegisterLink(provider){
      const links = state && state.remoteWex && state.remoteWex.registerLinks ? state.remoteWex.registerLinks : {};
      const url = links[provider] || '';
      const lower = String(url || '').toLowerCase();
      if (!(lower.indexOf('http://') === 0 || lower.indexOf('https://') === 0)) return toast('\u8FDC\u7A0B\u914D\u7F6E\u672A\u63D0\u4F9B\u6CE8\u518C\u94FE\u63A5');
      window.open(url, '_blank');
    }
    function nameOf(id){return state.providerNames[id] || id}
    function labelOrder(value){return String(value || '').split(',').filter(Boolean).map(nameOf).join(' > ')}
    function formatBytes(size){const units=['B','KB','MB'];let value=Number(size||0),i=0;while(value>=1024&&i<units.length-1){value/=1024;i++}return (i?value.toFixed(1):String(value)) + units[i]}
    function escapeHtml(value){return String(value || '').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
    function handleError(error){const text=error && error.message ? error.message : String(error || '\u64CD\u4F5C\u5931\u8D25');setMessage(text,true);toast(text)}
    $('reloadBtn').onclick = () => refresh().catch(handleError);
    $('drawerClose').onclick = closeDrawer;
    $('drawerMask').onclick = closeDrawer;
    function downloadDb(){window.open('/website/api/db','_blank')}
    function isMobileLayout(){return window.matchMedia('(max-width:1180px)').matches || window.matchMedia('(pointer:coarse)').matches || navigator.maxTouchPoints > 0 || /Android|iPhone|iPad|Mobile/i.test(navigator.userAgent)}
    function updateDrawerMode(){
      const enabled = isMobileLayout();
      document.body.classList.toggle('drawer-mode', enabled);
      relocateDetail(enabled);
      if (!enabled) closeDrawer();
    }
    function openDrawerIfMobile(){
      updateDrawerMode();
      if (document.body.classList.contains('drawer-mode')) document.body.classList.add('drawer-open');
    }
    function closeDrawer(){document.body.classList.remove('drawer-open')}
    function relocateDetail(enabled){
      const detail = document.querySelector('.detail');
      if (!detail) return;
      if (enabled) {
        if (detail.parentElement !== document.body) document.body.appendChild(detail);
        return;
      }
      const layout = $('mainLayout');
      if (layout && detail.parentElement !== layout) layout.appendChild(detail);
    }
